import json,pathlib,re,datetime; root=pathlib.Path("rdma-results");
for n in (56,57,58):
 metas=[json.loads(p.read_text()) for p in sorted(root.glob(f"matrix-v1-remaining-spark-7e64-{n:03d}-*.json"))]; values=[]
 for p in sorted(root.glob(f"matrix-v1-remaining-spark-7e64-{n:03d}-*.stdout")):
  rows=[l.split() for l in p.read_text().splitlines() if re.match(r"^\s*4096\s+\d+",l)]
  if rows:values.append(float(rows[-1][3]))
 if len(values)==2 and all("end_utc" in m for m in metas):
  overlap=(min(datetime.datetime.fromisoformat(m["end_utc"]) for m in metas)-max(datetime.datetime.fromisoformat(m["start_utc"]) for m in metas)).total_seconds();print(n,values,"aggregate",sum(values),"overlap_seconds",overlap)
